notes:
Example TypeScript snippet:

const it = client.chat.stream({ model: 'rwd-chat-1', prompt: 'Hello' })
for await (const msg of it) {
  console.log(msg.text)
}

Also export a convenience 'onMessage' to preserve callback ergonomics.

Example Go snippet:

it, err := client.ChatStream(ctx, params)
for it.Next() {
  msg := it.Value()
  fmt.Println(msg.Text)
}
if err := it.Err(); err != nil {
  // handle stream-level error
}
